    s = str(m)
    d = len(s)
    digits = sorted([int(c) for c in s])
    for k in range(10-d+1):
        if digits == list(range(k, k+d)):
            return m
    return None

results = []
for n in range(67, 1000):
    res = check(n)
    if res:
        results.append((n, res))
print(results)
